package com.bank.workfit;

import com.bank.workfit.model.CandidateAvailability;
import com.bank.workfit.model.WorkModel;
import com.bank.workfit.service.FitChecker;
import java.util.logging.*;

// Runnable demo: match a company's work model to a candidate's genuine availability.
public class WorkFitDemo {
    private static final Logger log = Logger.getLogger("WorkFit");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        // Company requires hybrid: 3 office days in Mumbai.
        WorkModel required = new WorkModel("HYBRID", 3, "Mumbai");
        FitChecker checker = new FitChecker(log);

        // Clean fit — candidate can do 3 days in Mumbai now.
        checker.check(required, new CandidateAvailability(3, "Mumbai", 0, null));

        // Fit with an honest constraint — needs 4 weeks to relocate.
        checker.check(required,
            new CandidateAvailability(3, "Mumbai", 4, "needs 4 weeks to relocate"));

        // Mismatch — candidate will only do 0 office days (fully remote demand).
        checker.check(required,
            new CandidateAvailability(0, "Remote", 0, "will only work fully remote"));
    }
}
