package com.bank.workfit.model;

// The company's required working pattern.
public class WorkModel {
    private final String type;       // ONSITE, HYBRID, REMOTE
    private final int officeDays;    // required office days per week
    private final String location;

    public WorkModel(String type, int officeDays, String location) {
        this.type = type;
        this.officeDays = officeDays;
        this.location = location;
    }

    public String getType() { return type; }
    public int getOfficeDays() { return officeDays; }
    public String getLocation() { return location; }
}
