package com.bank.workfit.model;

// What the candidate can genuinely commit to, including any stated constraint.
public class CandidateAvailability {
    private final int officeDays;
    private final String location;
    private final int relocationWeeks;   // 0 if already available
    private final String constraintNote; // honest note, null if none

    public CandidateAvailability(int officeDays, String location,
                                 int relocationWeeks, String constraintNote) {
        this.officeDays = officeDays;
        this.location = location;
        this.relocationWeeks = relocationWeeks;
        this.constraintNote = constraintNote;
    }

    public int getOfficeDays() { return officeDays; }
    public String getLocation() { return location; }
    public int getRelocationWeeks() { return relocationWeeks; }
    public String getConstraintNote() { return constraintNote; }
}
