package com.bank.workfit.service;

import com.bank.workfit.model.CandidateAvailability;
import com.bank.workfit.model.WorkModel;
import java.util.logging.*;

// Reports clean fit, fit-with-constraint, or a genuine mismatch — honestly.
public class FitChecker {
    private final Logger log;

    public FitChecker(Logger log) { this.log = log; }

    public void check(WorkModel required, CandidateAvailability avail) {
        boolean daysOk = avail.getOfficeDays() >= required.getOfficeDays();
        boolean locationOk = required.getLocation().equalsIgnoreCase(avail.getLocation());

        if (daysOk && locationOk && avail.getRelocationWeeks() == 0) {
            log.info(() -> "CLEAN FIT — " + required.getType() + " "
                + required.getOfficeDays() + " days in " + required.getLocation() + ".");
        } else if (daysOk && locationOk) {
            // Honest constraint, stated with a plan — still a fit.
            log.info(() -> "FIT WITH CONSTRAINT — ready in "
                + avail.getRelocationWeeks() + " weeks (" + avail.getConstraintNote() + ").");
        } else {
            // Rigid mismatch — surfaced early, not hidden.
            log.warning(() -> "MISMATCH — role needs " + required.getOfficeDays()
                + " days in " + required.getLocation()
                + "; candidate offers " + avail.getOfficeDays() + " in " + avail.getLocation()
                + " (" + avail.getConstraintNote() + ").");
        }
    }
}
